/**
 * config.js — continuous task
 * Sequences loaded from task/sequences/continuous_sequences.json
 * (single master copy — generated by task/generate_sequences.py)
 * mean_range=20..80, std_fixed=20, values in [0,100]
 *
 * Common structure lives in shared/config-base.js — this file supplies only
 * what differs for the continuous task.
 */
import sequencesData from '../../sequences/continuous_sequences.json';
import { buildConfig } from '../shared/config-base.js';

// Tutorial — fixed sequence: 5 values drawn from Normal(60, 20),
// all within 1σ of mean, at least 2 above and 2 below true_mean for
// pedagogical clarity. Generated with seed=5 of the constrained sampler.
const TUTORIAL_MEAN   = 60;
const TUTORIAL_STD    = 20;  // matches experiment std_fixed=20
const tutorialValues  = [48, 75, 38, 82, 57];  // mean≈60, spread ≈ std=20

export const config = buildConfig({
  taskType:      'continuous',
  sequencesData,
  tutorialValues,
  tutorialMean:  TUTORIAL_MEAN,
  tutorialStd:   TUTORIAL_STD,
  // No overrides — continuous currently uses all shared defaults.
});
